def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay keys[i] -> values[i] on the defaults mode=fast, level=3.

    Returns the resulting values in the order: mode, level, then any other
    keys in the order they first appear in keys. A repeated key takes its
    last value but keeps the position of its first appearance. Overriding
    a default replaces its value in place. The caller grants no capabilities.
    """
    merged: dict[str, str] = {"mode": "fast", "level": "3"}
    for key, value in zip(keys, values, strict=False):
        merged[key] = value
    return list(merged.values())


def test_no_overrides() -> None:
    assert settings([], []) == ["fast", "3"]


def test_override_default_mode() -> None:
    assert settings(["mode"], ["slow"]) == ["slow", "3"]


def test_override_default_level() -> None:
    assert settings(["level"], ["5"]) == ["fast", "5"]


def test_override_both_defaults_reversed_order() -> None:
    assert settings(["level", "mode"], ["7", "safe"]) == ["safe", "7"]


def test_extra_keys_appended_in_given_order() -> None:
    assert settings(["x", "y"], ["1", "2"]) == ["fast", "3", "1", "2"]


def test_mixed_defaults_and_extras() -> None:
    assert settings(["x", "mode"], ["1", "slow"]) == ["slow", "3", "1"]


def test_repeated_extra_key_last_wins_first_position() -> None:
    assert settings(["x", "y", "x"], ["1", "2", "3"]) == ["fast", "3", "3", "2"]


def test_repeated_default_key_last_wins() -> None:
    assert settings(["mode", "mode"], ["a", "b"]) == ["b", "3"]
